      SUBROUTINE CONSTRCC     CALCULATES PARTIALS AND FIRST-ORDER CONSTRAINTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      LOGICAL  LOGICC      DATA REARTH /6.3714E6/CC------------------------------------------------------------------      J = JCON      K = KCON      NP1 = NV1 + 1      DO 80 L1 = 1, NP1   80 A(L1) = 0.0      IF (J .EQ. 0 .AND. K .EQ. 0) GO TO 100      IF (J .EQ. 8 .AND. K .NE. 8) GO TO 110      IF (J .EQ. 9) GO TO 160      IF (J .EQ. 18) GO TO 800      IF (J .EQ. 100) GO TO 850      GO TO 200CC     SYSTEM LENGTH CONSTRAINTC  100 COC = LC/UFLOOR(1)      IF (NV3 .GE. 1) THEN        CW = 1.0/SD**2        A(1) = DE0 - COC        CALL CLI (LOGIC)        IF (LOGIC) GO TO 1000        IF (NV1 .GE. 1) THEN          DO 101 N = 1, NV1          A(N+1) = LCV(N)/UFLOOR(1)  101     CONTINUE        ENDIF      ENDIF  105 CALL GATHER      GO TO 1000CC     FLOOR COORDINATE CONSTRAINTC  110 IF (K .GE. 4) GO TO 120      IF (K .LE. 0) GO TO 900CC     CONSTRAINT ON POSITIONC      COC = X0(4,K)/UFLOOR(1)      IF (NV3 .GE. 1) THEN        CW = 1.0/SD**2        A(1) = DE0 - COC        IF (NV1 .GE. 1) THEN          DO 111 N = 1, NV1          IF (OVP(N)) A(N+1) = X0V(K,N)/UFLOOR(1)  111     CONTINUE        ENDIF      ENDIF      CALL GATHER      GO TO 1000CC     CONSTRAINT ON ANGLESC  120 IF (NV3 .GE. 1) CW = 1.0/SD**2      IF (K .EQ. 5) GO TO 130      IF (K .EQ. 6) GO TO 140      IF (K .EQ. 7) GO TO 150      IF (K .GE. 8) GO TO 900CC     CONSTRAINT ON YAWC      CSY = O(4,3,3)      SNY = O(4,3,1)      IF (CSY .EQ. 0.0) THEN        IF (SNY .GT. 0.0) YAW = 0.5*PI        IF (SNY .LT. 0.0) YAW = - 0.5*PI      ELSE        YAW = ATAN(SNY/CSY)        IF (CSY .LT. 0.0) THEN          SHIFT = SIGN(PI,SNY)          YAW = YAW + SHIFT        ENDIF        COC = YAW/UFLOOR(2)      ENDIFC      IF (NV3 .GE. 1) THEN        A(1) = DE0 - COC        IF (NV1 .GE. 1) THEN          DO 123 N = 1, NV1          IF (OVP(N)) THEN            DSNY = OV(3,1,N)            DCSY = OV(3,3,N)            A(N+1) = (CSY*DSNY - SNY*DCSY)/(CSY**2 + SNY**2)            A(N+1) = A(N+1)/UFLOOR(2)          ENDIF  123     CONTINUE        ENDIF      ENDIF      CALL GATHER      GO TO 1000CC     CONSTRAINT ON PITCHC  130 SINP = O(4,3,2)      COC = ASIN(SINP)/UFLOOR(2)      IF (NV3 .GE. 1) THEN        A(1) = DE0 - COC        IF (NV1 .GE. 1) THEN          COSP = SQRT(1.0 - SINP**2)          DO 131 N = 1, NV1          IF (OVP(N)) THEN            DSINP = OV(3,2,N)            A(N+1) = (DSINP/COSP)/UFLOOR(2)          ENDIF  131     CONTINUE        ENDIF      ENDIF      CALL GATHER      GO TO 1000CC     CONSTRAINT ON ROLLC  140 ROLL = ATAN(O(4,1,2)/O(4,2,2))      IF (O(4,2,2) .LT. 0.0) THEN        SHIFT = SIGN(PI,O(4,1,2))        ROLL = ROLL + SHIFT      ENDIF      COC = ROLL/UFLOOR(2)      IF (NV3 .GE. 1) THEN        A(1) = DE0 - COC        IF (NV1 .GE. 1) THEN        DO 143 N = 1, NV1        IF (OVP(N)) THEN          A(N+1) = (O(4,2,2)*OV(1,2,N) - O(4,1,2)*OV(2,2,N))/     1             (O(4,2,2)**2 + O(4,1,2)**2)          A(N+1) = A(N+1)/UFLOOR(2)        ENDIF  143   CONTINUE        ENDIF      ENDIF  145 CALL GATHER      GO TO 1000CC     CONSTRAINT ON ELEVATIONC  150 COC = (X0(4,2) +     1   0.5*((X0(4,1) - XINIT)**2 + (X0(4,3) - ZINIT)**2)/REARTH)     2   /UFLOOR(1)      IF (NV3 .LT. 1) GO TO 155      CW = 1.0/SD**2      A(1) = DE0 - COC      IF (NV1 .LT. 1) GO TO 155      DO 151 N = 1, NV1      IF (OVP(N)) THEN        A(N+1) = (X0V(2,N) + (X0V(1,N)*(X0(4,1) - XINIT)     1         + X0V(3,N)*(X0(4,3) - ZINIT))/REARTH)/UFLOOR(1)      ENDIF  151 CONTINUE  155 CALL GATHER      GO TO 1000CC     CONSTRAINT ON ALGEBRAIC COMBINATION OF MATRIX ELEMENTSC  160 COC = DATA(KCON)      IF (NV3 .LT. 1) GO TO 165      CW = 1.0/SD**2      A(1) = DE0 - COC      IF (NV1 .LT. 1) GO TO 165      DO 161 N = 1, NV1  161 A(N+1) = DATA(KCON+N)  165 CALL GATHER      NP1 = NV1 + 1      GO TO 1000CC     TRANSFER MATRIX CONSTRAINTSC  200 IF (R3P) CALL UPDAT3      IF (J .LT. -20) GO TO 210      IF (J .LT. -10) GO TO 250      IF (J .LT. 0) GO TO 350      GO TO 400CC     R2 MATRIX CONSTRAINTC  210 IF (NORD3 .LT. 1) GO TO 1000      IF (K .GT. 10) GO TO 230      J = - (J + 20)      IF (J .LT. 1 .OR. J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      FAC = UBEAM(K)/UBEAM(J)      COC = RC2(J,K)*FAC      IF (NV3 .GE. 1) THEN        CW = 1.0/SD**2        A(1) = DE0 - COC        CALL CLI(LOGIC)        IF (LOGIC) GO TO 1000C        IF (NV1 .GE. 1) THEN          DO 220 N = 1, NV1          IF (R2VP(N)) A(N+1) = R2V(J,K,N)*FAC  220     CONTINUE        ENDIF      ENDIF      CALL GATHER      GO TO 1000CC     T2 MATRIX CONSTRAINTC  230 IF (NORD3 .GE. 2) CALL CONSEC      GO TO 1000CC     AGS MACHINE CONSTRAINTC  250 J = - (JCON + 10)      IF (J .LT. 1 .OR. J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      IF (J .EQ. 5) GO TO 300      IF (NORD3 .GE. 1) CALL AGS      GO TO 1000CC     PHASE ADVANCE CONSTRAINTC  300 CALL PHASE      GO TO 1000CC     R MATRIX CONSTRAINTC  350 IF (NORD3 .LT. 1) GO TO 1000      J = - J      IF (K .GT. 10) GO TO 390      IF (J .LT. 1 .OR. J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      CALL RFIT      GO TO 1000CC     T MATRIX CONSTRAINTC  390 IF (NORD3 .GE. 2) CALL CONSEC      GO TO 1000CC     BEAM CONSTRAINTSC  400 IF (J .EQ. K) GO TO 500      IF (J .GT. 10 .AND. J .LE. 16) GO TO 600      IF (J .GT. 20 .AND. J .LE. 26) GO TO 510      IF (J .EQ. 0 .OR. J .EQ. 7) GO TO 700      IF (J .EQ. 27) GO TO 750CC     BEAM MATRIX CONSTRAINTC      IF (NORD3 .LT. 1) GO TO 1000      IF (.NOT. RECENT) CALL BEAM      FAC = 1.0/(UBEAM(J)*UBEAM(K))      IF (J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      COC = SIT(J,K)*FAC      IF (NV3 .LT. 1) GO TO 445      CW = 1.0/SD**2      A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 1000C      IF (NV1 .LT. 1) GO TO 445      DO 440 N = 1, NV1      IF (R2P) GO TO 410      IF (.NOT. SVP(N)) GO TO 440      SVJK = SV(J,K,N)      GO TO 430  410 SVJK = 0.0      IF (SVP(N)) THEN        DO 420 L1 = 1, 6        DO 420 L2 = 1, 6        SVJK = SVJK + RC2(J,L1)*SV(L1,L2,N)*RC2(K,L2)  420   CONTINUE      ENDIF      IF (R2VP(N)) THEN        DO 425 L1 = 1, 6        DO 425 L2 = 1, 6        SVJK = SVJK + R2V(J,L1,N)*SI(L1,L2)*RC2(K,L2)     1       + RC2(J,L1)*SI(L1,L2)*R2V(K,L2,N)  425   CONTINUE      ENDIF  430 A(N+1) = SVJK*FAC  440 CONTINUEC  445 CALL GATHER      GO TO 1000CC     BEAM SIZE CONSTRAINTC  500 IF (NORD3 .LT. 1) GO TO 1000      IF (J .GT. 6) GO TO 900      CALL EXTENT      GO TO 1000CC     ACCELERATOR PARAMETER BEAM CONSTRAINTC  510 CALL SNYDER      GO TO 1000CC     BEAM CORRELATION CONSTRAINTC  600 IF (NORD3 .LT. 1) GO TO 1000      J = JCON - 10      K = KCON      IF (J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      CALL CORREL      GO TO 1000CC     FIRST MOMENT CONSTRAINTC  700 IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      COC = 0.0      IF (SOFA) COC = CO(K)/UBEAM(K)      IF (NV3 .LT. 1) GO TO 745      CW = 1.0/SD**2      A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 1000C      IF (.NOT. SOFA) GO TO 745      IF (NV1 .LT. 1) GO TO 745      DO 740 N = 1, NV1      IF (CVP(N)) THEN        COTV = COV(K,N)        A(N+1) = COTV/UBEAM(K)      ENDIF  740 CONTINUE  745 CALL GATHER      GO TO 1000CC     CONSTRAINT ON ACCELERATOR FUNCTION ETAC  750 IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      COC = 0.0      IF (RAY) COC = ETA(K)/UBEAM(K)      IF (NV3 .LT. 1) GO TO 795      CW = 1.0/SD**2      A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 1000C      IF (.NOT. RAY) GO TO 795      IF (NV1 .LT. 1) GO TO 795      DO 790 N = 1, NV1      IF (EVP(N)) A(N+1) = ETAV(K,N)/UBEAM(K)  790 CONTINUE  795 CALL GATHER      GO TO 1000CC     SEXTUPOLE STRENGTH LIMITSC  800 IF (NORD3 .GE. 2) CALL CONSEC      GO TO 1000CC     NUMERICAL CONSTANTC  850 A(1) = - ACON      IF (NV3 .LT. 1) GO TO 870      DO 860 N = 1, NPVAR  860 A(N+1) = 0.0  870 CALL GATHER      GO TO 1000CC     ILLEGAL CONSTRAINTC  900 WRITE (NOUT,9804) 9804 FORMAT (' *** ERROR *** ILLEGAL FORM OF CONSTRAINT')      FLUSHL = .TRUE.      COC = 0.0C 1000 RETURN      END